    bronze_bookbindingawl = { name = "Bronast šilo za knjigoveštvo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast šilo za knjigoveštvo za knjigoveze." },
    silver_bookbindingawl = { name = "Srebrn šilo za knjigoveštvo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn šilo za knjigoveštvo za knjigoveze." },
    gilded_bookbindingawl = { name = "Pozlačen šilo za knjigoveštvo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen šilo za knjigoveštvo za knjigoveze." },
    jewel_set_bookbindingawl = { name = "Draguljast šilo za knjigoveštvo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast šilo za knjigoveštvo za knjigoveze." },
    royal_sovereign_bookbindingawl = { name = "Kraljevski suveren šilo za knjigoveštvo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren šilo za knjigoveštvo z biseri za krono." },
}
local BUILDINGS = {
    bookbindingawl_workshop = { name = "Bookbindingawl delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bookbindingawl_house = { name = "Bookbindingawl hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bookbindingawl_atelier = { name = "Mojstrski bookbindingawl atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookbindingawl_palace = { name = "Suverena bookbindingawl palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookbindingAwlMaker.ironStock=18; BookbindingAwlMaker.bronzeStock=14; BookbindingAwlMaker.woodStock=10; BookbindingAwlMaker.leatherStock=8; BookbindingAwlMaker.silverStock=8; BookbindingAwlMaker.goldStock=6; BookbindingAwlMaker.jewelStock=4; BookbindingAwlMaker.pearlStock=4
BookbindingAwlMaker.productStock = {}; BookbindingAwlMaker.buildings = {}; BookbindingAwlMaker.maker = nil; BookbindingAwlMaker.activeMaking = {}; BookbindingAwlMaker.totalProducts = 0; BookbindingAwlMaker.dayTimer = 0
function BookbindingAwlMaker.init() BookbindingAwlMaker.ironStock=18; BookbindingAwlMaker.bronzeStock=14; BookbindingAwlMaker.woodStock=10; BookbindingAwlMaker.leatherStock=8; BookbindingAwlMaker.silverStock=8; BookbindingAwlMaker.goldStock=6; BookbindingAwlMaker.jewelStock=4; BookbindingAwlMaker.pearlStock=4; BookbindingAwlMaker.productStock={}; BookbindingAwlMaker.buildings={}; BookbindingAwlMaker.maker=nil; BookbindingAwlMaker.activeMaking={}; BookbindingAwlMaker.totalProducts=0; BookbindingAwlMaker.dayTimer=0; print("[BookbindingAwlMaker] Royal Bookbinding Awl Maker System initialized (6 products, 4 buildings)") end
function BookbindingAwlMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookbindingAwlMaker.maker={name=n or ("Šilar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šilar najet: %s (spretnost: %d)",BookbindingAwlMaker.maker.name,s),"success") end; return true end
function BookbindingAwlMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookbindingAwlMaker.build(id) local ok,e=BookbindingAwlMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookbindingAwlMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookbindingAwlMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookbindingAwlMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookbindingAwlMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookbindingAwlMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookbindingAwlMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookbindingAwlMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookbindingAwlMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookbindingAwlMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookbindingAwlMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookbindingAwlMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookbindingAwlMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookbindingAwlMaker.buildings==0 then return false,"Potrebna šilna delavnica" end; if not BookbindingAwlMaker.maker then return false,"Potreben šilar" end; return true end
function BookbindingAwlMaker.make(pt,qty) qty=qty or 1; local ok,e=BookbindingAwlMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookbindingAwlMaker.ironStock=BookbindingAwlMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookbindingAwlMaker.bronzeStock=BookbindingAwlMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookbindingAwlMaker.woodStock=BookbindingAwlMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookbindingAwlMaker.leatherStock=BookbindingAwlMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookbindingAwlMaker.silverStock=BookbindingAwlMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookbindingAwlMaker.goldStock=BookbindingAwlMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookbindingAwlMaker.jewelStock=BookbindingAwlMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookbindingAwlMaker.pearlStock=BookbindingAwlMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookbindingAwlMaker.maker then t=math.max(1,t-math.floor(BookbindingAwlMaker.maker.skill/13)) end; table.insert(BookbindingAwlMaker.activeMaking,{id="bookbindingawl_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookbindingAwlMaker.completeMaking(m) local q=1.0+(BookbindingAwlMaker.getQualityBonus()/100); if BookbindingAwlMaker.maker then q=q+(BookbindingAwlMaker.maker.skill/140) end; q=math.min(2.5,q); BookbindingAwlMaker.productStock[m.productType]=(BookbindingAwlMaker.productStock[m.productType] or 0)+m.quantity; BookbindingAwlMaker.totalProducts=BookbindingAwlMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookbindingAwlMaker.maker then BookbindingAwlMaker.maker.itemsMade=BookbindingAwlMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookbindingAwlMaker.maker.skill=math.min(100,BookbindingAwlMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šilo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookbindingawl.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookbindingAwlMaker.update(dt) if not _G.state then return end; BookbindingAwlMaker.dayTimer=BookbindingAwlMaker.dayTimer+dt; if BookbindingAwlMaker.dayTimer>=30 then BookbindingAwlMaker.dayTimer=0; for i=#BookbindingAwlMaker.activeMaking,1,-1 do local m=BookbindingAwlMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookbindingAwlMaker.completeMaking(m); table.remove(BookbindingAwlMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookbindingAwlMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookbindingAwlMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookbindingAwlMaker.getStats() return {ironStock=BookbindingAwlMaker.ironStock,bronzeStock=BookbindingAwlMaker.bronzeStock,woodStock=BookbindingAwlMaker.woodStock,leatherStock=BookbindingAwlMaker.leatherStock,silverStock=BookbindingAwlMaker.silverStock,goldStock=BookbindingAwlMaker.goldStock,jewelStock=BookbindingAwlMaker.jewelStock,pearlStock=BookbindingAwlMaker.pearlStock,productStock=BookbindingAwlMaker.productStock,numBuildings=#BookbindingAwlMaker.buildings,hasMaker=BookbindingAwlMaker.maker~=nil,makerName=BookbindingAwlMaker.maker and BookbindingAwlMaker.maker.name or "—",makerSkill=BookbindingAwlMaker.maker and BookbindingAwlMaker.maker.skill or 0,activeMaking=#BookbindingAwlMaker.activeMaking,totalProducts=BookbindingAwlMaker.totalProducts} end
return BookbindingAwlMaker
